import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../../data/app_database.dart';
import '../../models/app_models.dart';
import '../common/ui.dart';
import 'bluetooth_scan_screen.dart';

class VehiclesScreen extends StatefulWidget { const VehiclesScreen({super.key}); @override State<VehiclesScreen> createState()=>_VehiclesScreenState(); }
class _VehiclesScreenState extends State<VehiclesScreen>{List<Vehicle> items=[];Future<void> load()async{final v=await AppDatabase.instance.vehicles();if(mounted)setState(()=>items=v);}@override void initState(){super.initState();load();}
 Future<void> edit([Vehicle? existing])async{final name=TextEditingController(text:existing?.name??''),mileage=TextEditingController(text:(existing?.referenceMileage??40).toString()),price=TextEditingController(text:(existing?.fuelPrice??105).toString());final form=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(existing==null?'Add vehicle':'Edit vehicle'),content:Form(key:form,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'Vehicle name'),validator:(v)=>v==null||v.trim().isEmpty?'Enter vehicle name':null),TextFormField(controller:mileage,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Reference mileage (km/L)'),validator:(v)=>double.tryParse(v??'')==null||double.parse(v!)<=0?'Enter valid mileage':null),TextFormField(controller:price,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Fuel price (₹/L)'),validator:(v)=>double.tryParse(v??'')==null||double.parse(v!)<0?'Enter valid fuel price':null)])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),TextButton(onPressed:(){if(form.currentState!.validate())Navigator.pop(ctx,true);},child:const Text('Save'))]));if(ok==true){final v=Vehicle(id:existing?.id??const Uuid().v4(),name:name.text.trim(),referenceMileage:double.parse(mileage.text),fuelPrice:double.parse(price.text));await AppDatabase.instance.saveVehicle(v);await load();}}
 @override Widget build(BuildContext context)=>Scaffold(floatingActionButton:FloatingActionButton(onPressed:()=>edit(),child:const Icon(Icons.add)),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.only(bottom:90),children:[const PageTitle('My vehicles'),Padding(padding:const EdgeInsets.fromLTRB(20,0,20,14),child:OutlinedButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const BluetoothScanScreen())),icon:const Icon(Icons.bluetooth_searching),label:const Text('Scan Bluetooth devices'))),if(items.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Panel(child:Text('No vehicles yet. Tap + to add your bike or car.'))),...items.map((v)=>Padding(padding:const EdgeInsets.fromLTRB(20,0,20,14),child:Panel(child:Row(children:[const Icon(Icons.two_wheeler,size:34,color:Color(0xFF13D3C2)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(v.name,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17)),Text('${v.referenceMileage} km/L · ₹${v.fuelPrice}/L',style:const TextStyle(color:Colors.white60))])),IconButton(onPressed:()=>edit(v),icon:const Icon(Icons.edit_outlined)),IconButton(onPressed:()async{if(items.length==1){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Keep at least one vehicle in your garage.')));return;}await AppDatabase.instance.deleteVehicle(v.id);await load();},icon:const Icon(Icons.delete_outline))])))])));
}
